#!/usr/bin/env bash
# Fix: Hardware Allocate/Reassign user picker truncated to 10 users.
# Generated by gen_deploy_users_pagesize_fix.py - do not hand-edit.
#
# Run this from the repo root on the server.
set -uo pipefail

sec() { echo ""; echo "=== $* ==="; echo "=== $* ===" >&2; }

FAIL=0

sec "0. Confirm repo root"
if [ ! -d "frontend/actions/assets" ]; then
    echo "!!! frontend/actions/assets not found under $(pwd) - run this from the repo root."
    exit 1
fi

sec "1. Pre-flight: verify the touched file is exactly what was confirmed"
if [ ! -f "frontend/actions/assets/loadAssetLookups.ts" ]; then
    echo "!!! frontend/actions/assets/loadAssetLookups.ts not found - aborting, nothing written yet."
    FAIL=1
else
    h=$(git hash-object "frontend/actions/assets/loadAssetLookups.ts")
    if [ "$h" != "faf5963eff3f70bcc128181c2ee5fde5e07a13d7" ]; then
        echo "!!! frontend/actions/assets/loadAssetLookups.ts does not match the expected pre-deploy hash."
        echo "    expected: faf5963eff3f70bcc128181c2ee5fde5e07a13d7"
        echo "    actual:   $h"
        echo "    This file has changed on the server since it was last verified - do not proceed."
        FAIL=1
    fi
fi

if [ "$FAIL" != "0" ]; then
    echo ""
    echo ">>> Pre-flight checks failed - nothing was written. See messages above."
    exit 1
fi
echo "All pre-flight checks passed."

sec "2. Writing files"
mkdir -p "$(dirname "frontend/actions/assets/loadAssetLookups.ts")"
base64 -d > "frontend/actions/assets/loadAssetLookups.ts.tmp" <<'B64EOF'

B64EOF
mv "frontend/actions/assets/loadAssetLookups.ts.tmp" "frontend/actions/assets/loadAssetLookups.ts"
echo "wrote frontend/actions/assets/loadAssetLookups.ts"

sec "3. Post-flight: verify the written file matches the expected final hash"
POSTFAIL=0
h=$(git hash-object "frontend/actions/assets/loadAssetLookups.ts")
if [ "$h" != "551ec67de4a0c99f3ffd45cbed4763b2e1786e10" ]; then
    echo "!!! frontend/actions/assets/loadAssetLookups.ts does not match the expected post-deploy hash (expected 551ec67de4a0c99f3ffd45cbed4763b2e1786e10, got $h)"
    POSTFAIL=1
else
    echo "OK: frontend/actions/assets/loadAssetLookups.ts"
fi

if [ "$POSTFAIL" != "0" ]; then
    echo ""
    echo ">>> Post-deploy verification failed - do not restart the frontend; investigate before proceeding."
    exit 1
fi

sec "4. Done"
echo "File written and verified. Next steps:"
echo "  1. git add -A && git commit  (commit this on the server's own checkout)"
echo "  2. docker compose build frontend && docker compose up -d frontend"
echo "  3. As Super Admin or IT Admin, open Hardware Assets -> Allocate (or Reassign) on any asset, search the User field for someone NOT in the first ~10 alphabetically, and confirm they now appear"
echo "  4. Confirm the total user count in the search box roughly matches the real total headcount (Users admin screen, or the org's known user count)"
echo ">>> DONE"
